use std::{collections::HashMap,env,fs,path::Path};
use mushroom_solar::{electrical::ElectricalDesignBasis,thermal::NmotParameters,thermal_electrical::{evaluate_coupled_step,CoupledInput},weather::parse_nasa_power_hourly_csv};
#[derive(Clone)]struct R{ts:i64,g:String,c:String,d:f64,f:f64,r:f64,t:f64,pv:f64,land:f64}
fn main(){let a:Vec<String>=env::args().collect();assert!(a.len()>=5,"usage: annual-electrical-preaudit TIMESTEP.csv MONTHLY.csv WEATHER.csv OUTDIR");let out=&a[4];fs::create_dir_all(out).unwrap();
let mut rows=Vec::new();for(lno,l)in fs::read_to_string(&a[1]).unwrap().lines().enumerate().skip(1){let x:Vec<&str>=l.split(',').collect();assert!(x.len()>=15,"bad timestep row {lno}");assert_eq!(x[5],"true");assert_eq!(x[3],"4x24");assert_eq!(x[4],"16");assert_eq!(x[14],"DEVELOPMENT_NOT_SERIS");rows.push(R{ts:x[0].parse().unwrap(),g:x[1].into(),c:x[2].into(),d:x[6].parse().unwrap(),f:x[7].parse().unwrap(),r:x[8].parse().unwrap(),t:x[9].parse().unwrap(),pv:x[10].parse().unwrap(),land:x[11].parse().unwrap()});}
assert_eq!(rows.len(),87840);for w in rows.windows(2){if w[0].g==w[1].g&&w[0].c==w[1].c{assert_eq!(w[1].ts-w[0].ts,3600);}}
let mut frozen=HashMap::new();for l in fs::read_to_string(&a[2]).unwrap().lines().skip(1){let x:Vec<&str>=l.split(',').collect();frozen.insert((x[2].to_string(),x[1].to_string(),x[3].parse::<u32>().unwrap()),[x[4].parse().unwrap(),x[5].parse().unwrap(),x[6].parse().unwrap(),x[7].parse().unwrap()]);}
let mut monthly:HashMap<(String,String,u32),[f64;4]>=HashMap::new();for x in &rows{let month=month_from_epoch(x.ts);let q=monthly.entry((x.g.clone(),x.c.clone(),month)).or_insert([0.;4]);q[0]+=x.d;q[1]+=x.f;q[2]+=x.r;q[3]+=x.t;}
let mut rec=String::from("candidate,resource_contract,month,component,frozen_wh,reconstructed_wh,abs_residual_wh,relative_residual,tolerance_wh,pass\n");let mut maxres:f64=0.;for(k,v)in&frozen{let z=monthly.get(k).unwrap();for(i,n)in["direct","diffuse","ground","total"].iter().enumerate(){let er=(z[i]-v[i]).abs();let rel=if v[i].abs()>1e-12{er/v[i].abs()}else{0.};let tol=1e-6_f64.max(1e-9*v[i].abs());assert!(er<=tol,"monthly mismatch {:?} {} {}>{}",k,n,er,tol);maxres=maxres.max(er);rec+=&format!("{},{},{},{},{:.9},{:.9},{:.3e},{:.3e},{:.3e},true\n",k.0,k.1,k.2,n,v[i],z[i],er,rel,tol);}}
fs::write(Path::new(out).join("monthly_aggregate_back.csv"),rec).unwrap();
let(raw,qc)=parse_nasa_power_hourly_csv(&fs::read_to_string(&a[3]).unwrap()).unwrap();assert_eq!(raw.len(),8784);assert!(qc.is_empty());let wm:HashMap<i64,f64>=raw.into_iter().map(|w|(w.timestamp_utc_s,w.ambient_temperature_c)).collect();
let e=ElectricalDesignBasis::canadian_solar_cs62_48tm_460h();let mut summary=String::from("candidate,resource_contract,design_basis,nmot_c,year,timesteps,gross_dc_wh,ac_wh,auxiliary_wh,net_wh,pv_norm_net_wh_m2pv,land_norm_net_wh_m2land,mean_module_temp_c,irradiance_weighted_mean_module_temp_c,p95_module_temp_c,max_module_temp_c,missing_rejected_rows,electrical_scenario,status\n");
for nmot in[39.,42.,45.]{let tp=NmotParameters{nmot_c:nmot,reference_ambient_c:20.,reference_irradiance_w_m2:800.};let mut groups:HashMap<(String,String),(f64,f64,f64,f64,Vec<f64>,f64,f64,f64)>=HashMap::new();for x in&rows{let ta=*wm.get(&x.ts).expect("exact T2M timestamp");let poa=x.t/x.pv;let o=evaluate_coupled_step(CoupledInput{poa_w_m2:poa,ambient_temp_c:ta,dt_hours:1.,auxiliary_power_w:0.},tp,&e).unwrap();let z=groups.entry((x.g.clone(),x.c.clone())).or_insert((0.,0.,0.,0.,Vec::new(),0.,x.pv,x.land));z.0+=o.delivered_dc_w;z.1+=o.ac_w;z.2+=o.net_energy_wh;z.3+=o.module_temp_c;z.4.push(o.module_temp_c);z.5+=o.module_temp_c*poa;}
 for((g,c),(dc,ac,net,tsum,mut temps,wt,pv,land))in groups{temps.sort_by(|a,b|a.partial_cmp(b).unwrap());let p95=temps[((temps.len()-1)as f64*0.95).round()as usize];let max=*temps.last().unwrap();let irrsum: f64=rows.iter().filter(|x|x.g==g&&x.c==c).map(|x|x.t/x.pv).sum();summary+=&format!("{g},{c},CS6.2-48TM-460H,{nmot:.1},2024,8784,{dc:.9},{ac:.9},0.000000000,{net:.9},{:.9},{:.9},{:.6},{:.6},{p95:.6},{max:.6},0,IDEAL_ZERO_DECLARED_ELECTRICAL_LOSSES__P_AUX_ZERO_FIXED_BASELINE,DEVELOPMENT_NOT_SERIS_PRE_AUDIT_NOT_PROMOTED\n",net/pv,net/land,tsum/8784.,wt/irrsum);}
}
fs::write(Path::new(out).join("annual_electrical_preaudit.csv"),summary).unwrap();println!("PASS monthly aggregate-back; max residual {maxres:.3e} Wh; pre-audit electrical package generated without ranking");}
fn month_from_epoch(ts:i64)->u32{let days=ts.div_euclid(86400);let(z,_,_)=civil_from_days(days);z}
fn civil_from_days(days:i64)->(u32,i32,u32){let z=days+719468;let era=if z>=0{z}else{z-146096}/146097;let doe=z-era*146097;let yoe=(doe-doe/1460+doe/36524-doe/146096)/365;let y=yoe+era*400;let doy=doe-(365*yoe+yoe/4-yoe/100);let mp=(5*doy+2)/153;let d=doy-(153*mp+2)/5+1;let m=mp+if mp<10{3}else{-9};let yy=y+if m<=2{1}else{0};(m as u32,yy as i32,d as u32)}